def _spina_v24_cilog_parse_day(value):
    try:
        s = str(value or "").strip()
        if not s:
            return None
        # Common format is YYYY-MM-DD HH:MM:SS. Only first 10 characters are needed.
        return datetime.strptime(s[:10], "%Y-%m-%d").date()
    except Exception:
        return None

